function FlowDiagram({ navigate }) {
  const rawNodes = [{"id":"product_list","data":{"label":"상품 목록 화면"},"sourcePosition":"right","targetPosition":"left","style":{"background":"#fff","border":"2px solid #1677ff","borderRadius":8,"color":"#1677ff","fontWeight":600,"fontSize":13,"width":180,"height":60,"display":"flex","alignItems":"center","justifyContent":"center","textAlign":"center","padding":"0 12px","cursor":"pointer"}},{"id":"product_register","data":{"label":"상품 등록 화면"},"sourcePosition":"right","targetPosition":"left","style":{"background":"#f0f5ff","border":"1.5px dashed #4096ff","borderRadius":6,"color":"#4096ff","fontWeight":500,"fontSize":12,"width":160,"height":52,"display":"flex","alignItems":"center","justifyContent":"center","textAlign":"center","padding":"0 10px","cursor":"pointer"}}]
  const rawEdges = [{"id":"e_0","source":"product_list","target":"product_register","type":"smoothstep","markerEnd":{"type":"arrowclosed","color":"#1677ff","width":16,"height":16},"style":{"stroke":"#1677ff","strokeWidth":1.5,"opacity":0.65}},{"id":"e_1","source":"product_register","target":"product_list","type":"smoothstep","markerEnd":{"type":"arrowclosed","color":"#1677ff","width":16,"height":16},"style":{"stroke":"#1677ff","strokeWidth":1.5,"opacity":0.65}}]
  const [flowKey, setFlowKey] = React.useState(0)

  // dagre로 레이아웃 계산 (LR 방향)
  const layoutedNodes = React.useMemo(() => {
    try {
      const g = new dagre.graphlib.Graph()
      g.setDefaultEdgeLabel(() => ({}))
      g.setGraph({ rankdir: 'LR', nodesep: 60, ranksep: 120, marginx: 40, marginy: 40 })
      rawNodes.forEach(n => g.setNode(n.id, { width: n.style.width, height: n.style.height }))
      rawEdges.forEach(e => g.setEdge(e.source, e.target))
      dagre.layout(g)
      return rawNodes.map(n => {
        const pos = g.node(n.id)
        return { ...n, position: { x: pos.x - n.style.width / 2, y: pos.y - n.style.height / 2 } }
      })
    } catch {
      return rawNodes.map((n, i) => ({ ...n, position: { x: (i % 3) * 280 + 40, y: Math.floor(i / 3) * 140 + 40 } }))
    }
  }, [flowKey])

  return (
    <div style={{ padding: 24 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 8 }}>
        <Typography.Title level={4} style={{ margin: 0 }}>사용자 Flow 다이어그램</Typography.Title>
        <AntButton size="small" onClick={() => setFlowKey(k => k + 1)}>↺ 새로고침</AntButton>
      </div>
      <Typography.Text type="secondary" style={{ display: 'block', marginBottom: 16 }}>노드를 클릭하면 해당 화면으로 이동합니다.</Typography.Text>
      <div style={{ height: 520, border: '1px solid #e0e0e0', borderRadius: 8, overflow: 'hidden', background: '#fafafa' }}>
        <ReactFlow
          key={flowKey}
          nodes={layoutedNodes}
          edges={rawEdges}
          onNodeClick={(_, node) => navigate(node.id)}
          fitView
          fitViewOptions={{ padding: 0.3 }}
          proOptions={{ hideAttribution: true }}
          nodesDraggable={true}
        >
          <Controls />
          <Background color="#e8e8e8" gap={20} size={1} />
        </ReactFlow>
      </div>
    </div>
  )
}

function Screen_product_list({ navigate }) {
  const [rows, setRows] = useState([
    { id: 'PRD-001', name: '무신사 스탠다드 오버핏 티셔츠', brand: '무신사 스탠다드', price: '₩29,000', status: '판매중' },
    { id: 'PRD-002', name: '아디다스 클래식 트랙 재킷', brand: '아디다스', price: '₩89,000', status: '판매중지' },
    { id: 'PRD-003', name: '나이키 에어맥스 270', brand: '나이키', price: '₩149,000', status: '품절' },
  ]);
  const [keyword, setKeyword] = useState('');
  const [brandKw, setBrandKw] = useState('');
  const [status, setStatus] = useState('전체');
  const [selected, setSelected] = useState([]);
  const [delOpen, setDelOpen] = useState(false);
  const allChecked = selected.length === rows.length && rows.length > 0;
  const indeterminate = selected.length > 0 && selected.length < rows.length;
  const search = () => setSelected([]);
  const reset = () => { setKeyword(''); setBrandKw(''); setStatus('전체'); setSelected([]); };
  const del = () => {
    setRows(rows.filter(r => !selected.includes(r.id)));
    setSelected([]);
    setDelOpen(false);
    message.success('선택한 상품이 삭제되었습니다.');
  };
  const toggleRow = (id) => setSelected(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  const toggleAll = () => setSelected(allChecked ? [] : rows.map(r => r.id));
  const statusColor = (s) => ({ '판매중': 'green', '판매중지': 'red', '품절': 'yellow' }[s] || 'gray');
  const columns = [
    { key: 'selected', headerName: '', headerControlType: 'checkbox', headerControlChecked: allChecked, headerControlIndeterminate: indeterminate },
    { key: 'id', headerName: '상품ID' },
    { key: 'name', headerName: '상품명' },
    { key: 'brand', headerName: '브랜드' },
    { key: 'price', headerName: '판매가' },
    { key: 'status', headerName: '판매 상태' },
  ];
  const tableRows = rows.map(r => [
    <Checkbox showLabel={false} checked={selected.includes(r.id)} onChange={() => toggleRow(r.id)} />,
    r.id,
    <TextButton onClick={() => navigate('product_register')}>{r.name}</TextButton>,
    r.brand,
    r.price,
    <Tag labelText={r.status} color={statusColor(r.status)} />,
  ]);
  return (
    <div style={{ padding: 'var(--mcds-registration-shell-padding-top) var(--mcds-registration-shell-padding-right) var(--mcds-registration-shell-padding-bottom) var(--mcds-registration-shell-padding-left)' }}>
      <AdminListRecipeLayout
        title="상품 목록"
        search={
          <RecipeSearchArea
            fields={[
              { key: 'name', label: '상품명', control: <TextField value={keyword} onChange={setKeyword} placeholder="상품명 입력" /> },
              { key: 'brand', label: '브랜드명', control: <TextField value={brandKw} onChange={setBrandKw} placeholder="브랜드명 입력" /> },
              { key: 'status', label: '판매 상태', control: <Select value={status} onChange={setStatus} options={[{ label: '전체', value: '전체' }, { label: '판매중', value: '판매중' }, { label: '판매중지', value: '판매중지' }, { label: '품절', value: '품절' }]} /> },
            ]}
            leftActions={<><Button onClick={search}>검색</Button><Button type="secondary" onClick={reset}>초기화</Button></>}
          />
        }
        results={
          <RecipeResultsTable
            title={`상품 목록 (${rows.length}건)`}
            columns={columns}
            rows={tableRows}
            actions={
              <>
                <Button type="secondary" size={36} disabled={selected.length === 0} onClick={() => setDelOpen(true)}>삭제</Button>
                <Button onClick={() => navigate('product_register')}>상품 등록</Button>
              </>
            }
            emptyState={{ title: '조회 결과가 없습니다.', description: '검색 조건을 확인해 주세요.' }}
            pagination={{ current: 1, total: 5, onChange: () => {} }}
          />
        }
      />
      {delOpen && (
        <ConfirmActionDialog
          open
          title={`선택한 ${selected.length}개의 상품을 삭제하시겠습니까? 삭제된 상품은 복구할 수 없습니다.`}
          confirmAction={<Button onClick={del}>삭제</Button>}
          cancelAction={<Button type="secondary" onClick={() => setDelOpen(false)}>취소</Button>}
          onClose={() => setDelOpen(false)}
        />
      )}
    </div>
  );
}

function Screen_product_register({ navigate }) {
  const [name, setName] = useState('');
  const [brand, setBrand] = useState('');
  const [category, setCategory] = useState('');
  const [price, setPrice] = useState('');
  const [status, setStatus] = useState('판매중');
  const [desc, setDesc] = useState('');
  const [files, setFiles] = useState([]);
  const [sec1, setSec1] = useState(true);
  const [sec2, setSec2] = useState(true);

  const brandOptions = [
    { label: '무신사 스탠다드', value: '무신사 스탠다드' },
    { label: '아디다스', value: '아디다스' },
    { label: '나이키', value: '나이키' },
  ];

  const categoryOptions = [
    { label: '상의', value: '상의' },
    { label: '하의', value: '하의' },
    { label: '아우터', value: '아우터' },
    { label: '신발', value: '신발' },
  ];

  const statusOptions = [
    { label: '판매중', value: '판매중' },
    { label: '판매중지', value: '판매중지' },
    { label: '품절', value: '품절' },
  ];

  const handleSave = () => {
    message.success('상품이 등록되었습니다.');
    navigate('product_list');
  };

  const sections = (
    <RecipeAccordionSections
      sections={[
        {
          id: 'basic',
          title: '기본 정보',
          open: sec1,
          onToggle: () => setSec1(!sec1),
          body: (
            <Stack gap={12}>
              <FormField label="상품명" required>
                <TextField value={name} onChange={setName} placeholder="상품명을 입력하세요" />
              </FormField>
              <FormField label="브랜드" required>
                <AutoComplete
                  options={brandOptions}
                  value={brand}
                  onChange={setBrand}
                  onSearch={setBrand}
                  placeholder="브랜드명을 입력하세요"
                  allowClear
                />
              </FormField>
              <FormField label="카테고리" required>
                <Select
                  options={categoryOptions}
                  value={category || '상의'}
                  onChange={setCategory}
                />
              </FormField>
              <FormField label="판매가" required>
                <NumberInput value={price} onChange={setPrice} placeholder="판매가를 입력하세요" />
              </FormField>
              <FormField label="판매 상태" required>
                <Select
                  options={statusOptions}
                  value={status}
                  onChange={setStatus}
                />
              </FormField>
            </Stack>
          ),
        },
        {
          id: 'detail',
          title: '상세 정보',
          open: sec2,
          onToggle: () => setSec2(!sec2),
          body: (
            <Stack gap={12}>
              <FormField label="상품 설명" required>
                <TextArea
                  value={desc}
                  onChange={setDesc}
                  placeholder="상품 설명을 입력하세요"
                />
              </FormField>
              <FormField label="대표 이미지" required>
                <UploadPanel
                  label="대표 이미지"
                  description="JPG, PNG 형식의 이미지를 업로드하세요 (최대 5MB)"
                  files={files}
                  accept=".jpg,.jpeg,.png"
                  multiple={false}
                  onSelect={(f) => setFiles(Array.from(f))}
                  onRemove={(f) => setFiles(files.filter((x) => x !== f))}
                />
              </FormField>
            </Stack>
          ),
        },
      ]}
    />
  );

  const footer = (
    <FooterActionBar
      leading={
        <TextButton iconLeft={<IconArrowLeft />} onClick={() => navigate('product_list')}>
          목록으로
        </TextButton>
      }
      trailing={
        <Inline gap={8}>
          <Button type="secondary" onClick={() => navigate('product_list')}>취소</Button>
          <Button onClick={handleSave}>저장</Button>
        </Inline>
      }
    />
  );

  return (
    <AdminRegistrationRecipeLayout
      title="상품 등록"
      variant="basic"
      sections={sections}
      stickyActions={footer}
    />
  );
}

